
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"HotNeonAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
	
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.anl.koh!=undefined){
			
			if(gameController.vkc!=parseInt(tmpMess[1])){
				
			gameController.yrc=parseInt(tmpMess[1]);	
			gameController.vkc=parseInt(tmpMess[1]);	
			gameController.anl.koh.klt("creditd", "#heo", [gameController.gjh(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
